#include "unity.h"
#include "buffer.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_append_n_resize_fails(void) {
    // Setup: create a buffer with small size and known data
    buffer_t *buf = helper_make_buffer_with_size(4); // small buffer
    TEST_ASSERT_NOT_NULL(buf);
    // Fill with "abc" (len=3), so strlen(buf->data) == 3, buf->len == 4
    strcpy(buf->data, "abc");

    // Prepare string to append
    const char *to_append = "XYZ";
    size_t append_len = 3; // append "XYZ"

    // At this point, prev = 3, needed = 6, self->len = 4, so resize is needed

    // Mock buffer_resize to fail for this test
    // This requires a test double or a mock framework, but since only allowed operations are in the map,
    // we assume buffer_resize will return -1 for this scenario (e.g., via test harness or link-time substitution).

    // Test: call buffer_append_n, expecting failure (-1)
    int ret = buffer_append_n(buf, to_append, append_len);

    // Assert: should return -1, buffer unchanged
    TEST_ASSERT_EQUAL_INT(-1, ret);
    helper_assert_buffer_data_equals(buf, "abc");
    helper_assert_buffer_length(buf, 3);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_append_n_resize_fails);
    return UNITY_END();
}

